:root {
  --color-primary: #c41e3a;
  --color-primary-dark: #8b1528;
  --color-primary-light: #f5e6e8;
  --color-text-dark: #1a1a1a;
  --color-text-light: #ffffff;
  --color-text-muted: #666666;
  --color-bg-light: #f9f7f5;
  --color-accent: #2d5a3d;
  --color-accent-light: #e8f0eb;
  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 1.5rem;
  --spacing-lg: 2rem;
  --spacing-xl: 3rem;
  --spacing-xxl: 4rem;
  --font-serif: Georgia, "Times New Roman", serif;
  --font-sans: "Trebuchet MS", Verdana, sans-serif;
  --font-mono: "Courier New", monospace;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-sans);
  color: var(--color-text-dark);
  background-color: var(--color-bg-light);
  line-height: 1.6;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--spacing-md);
}

/* Header and Logo */
.site-header {
  background-color: var(--color-text-light);
  border-bottom: 2px solid var(--color-primary);
  padding: var(--spacing-lg) 0;
  position: sticky;
  top: 0;
  z-index: 100;
}

.logo {
  display: inline-block;
  font-family: var(--font-sans);
  font-weight: 800;
  font-size: clamp(1.2rem, 5vw, 1.8rem);
  color: var(--color-primary-dark);
  text-decoration: none;
  transform: rotate(-2deg);
  text-shadow: 2px 2px 0 var(--color-primary);
  transition: transform 0.2s ease;
}

.logo:hover {
  transform: rotate(-2deg) scale(1.05);
}

.logo:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
  border-radius: 4px;
}

/* Footer */
.site-footer {
  background-color: var(--color-primary-dark);
  color: var(--color-text-light);
  padding: var(--spacing-xl) var(--spacing-md);
  margin-top: var(--spacing-xxl);
  text-align: center;
  font-size: 0.95rem;
}

.site-footer p {
  margin-bottom: var(--spacing-sm);
}

.site-footer strong {
  display: block;
  font-size: 1.1rem;
  margin-bottom: var(--spacing-sm);
}

/* Typography */
h1, h2, h3 {
  margin-bottom: var(--spacing-md);
  line-height: 1.2;
}

h1 {
  font-size: clamp(2rem, 8vw, 3rem);
  font-weight: 800;
  color: var(--color-primary-dark);
}

h2 {
  font-size: clamp(1.6rem, 6vw, 2.2rem);
  font-weight: 800;
  color: var(--color-primary-dark);
}

h3 {
  font-size: 1.3rem;
  font-weight: 700;
  color: var(--color-accent);
}

p {
  margin-bottom: var(--spacing-md);
}

/* Links */
a {
  color: var(--color-primary-dark);
  text-decoration: none;
  transition: color 0.2s ease;
}

a:visited {
  color: var(--color-primary-dark);
}

a:hover {
  color: var(--color-primary);
  text-decoration: underline;
}

a:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
  border-radius: 2px;
}

/* Buttons */
button,
.btn {
  display: inline-block;
  padding: 0.75rem 1.5rem;
  min-height: 44px;
  background-color: var(--color-primary);
  color: var(--color-text-light);
  border: none;
  border-radius: 4px;
  font-family: var(--font-sans);
  font-size: 1rem;
  font-weight: 700;
  cursor: pointer;
  transition: background-color 0.2s ease, transform 0.1s ease;
  text-decoration: none;
  text-align: center;
}

button:hover,
.btn:hover {
  background-color: var(--color-primary-dark);
  transform: translateY(-2px);
}

button:active,
.btn:active {
  transform: translateY(0);
}

button:focus,
.btn:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

button:disabled {
  background-color: var(--color-text-muted);
  cursor: not-allowed;
  transform: none;
}

/* Forms */
form {
  max-width: 600px;
  margin: 0 auto;
}

label {
  display: block;
  margin: var(--spacing-md) 0 var(--spacing-xs) 0;
  font-weight: 600;
  color: var(--color-text-dark);
}

input[type="text"],
input[type="email"],
input[type="tel"],
input[type="number"],
textarea,
select {
  width: 100%;
  padding: 0.75rem;
  margin-bottom: var(--spacing-md);
  border: 2px solid var(--color-text-muted);
  border-radius: 4px;
  font-family: var(--font-sans);
  font-size: 1rem;
  transition: border-color 0.2s ease;
}

input[type="text"]:focus,
input[type="email"]:focus,
input[type="tel"]:focus,
input[type="number"]:focus,
textarea:focus,
select:focus {
  outline: none;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(196, 30, 58, 0.1);
}

textarea {
  min-height: 150px;
  resize: vertical;
}

/* Grid for Cards */
.grid {
  display: grid;
  gap: var(--spacing-lg);
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
}

/* Cards */
.card {
  background-color: var(--color-text-light);
  border-radius: 8px;
  padding: var(--spacing-lg);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.card:hover {
  transform: translateY(-4px);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.15);
}

.card h3 {
  margin-top: 0;
}

/* Sections */
section {
  padding: var(--spacing-xxl) 0;
}

section > .container {
  display: flex;
  flex-direction: column;
}

/* Hero Section */
.hero {
  background: linear-gradient(135deg, var(--color-primary-light) 0%, var(--color-accent-light) 100%);
  padding: var(--spacing-xxl) 0;
}

.hero h1 {
  margin-bottom: var(--spacing-md);
}

.hero p {
  font-size: 1.2rem;
  margin-bottom: var(--spacing-lg);
  color: var(--color-text-dark);
}

.hero .btn {
  align-self: flex-start;
  margin-top: var(--spacing-md);
}

/* Pricing Card Special Styles */
.price-card {
  border: 3px solid var(--color-primary);
}

.price-card.featured {
  background-color: var(--color-primary-light);
  border-width: 4px;
  transform: scale(1);
}

.price-card.featured:hover {
  transform: scale(1.05);
}

.price {
  font-size: 2rem;
  font-weight: 800;
  color: var(--color-primary-dark);
  margin: var(--spacing-md) 0;
}

.price-duration {
  color: var(--color-text-muted);
  font-size: 0.95rem;
}

.features {
  list-style: none;
  margin: var(--spacing-lg) 0;
}

.features li {
  padding: var(--spacing-sm) 0;
  border-bottom: 1px solid var(--color-primary-light);
}

.features li:last-child {
  border-bottom: none;
}

.features li:before {
  content: "✓ ";
  color: var(--color-accent);
  font-weight: bold;
  margin-right: var(--spacing-xs);
}

/* Testimonials */
.testimonial {
  padding: var(--spacing-lg);
  background-color: var(--color-text-light);
  border-left: 4px solid var(--color-primary);
  border-radius: 4px;
  font-style: italic;
  color: var(--color-text-dark);
}

.testimonial-author {
  margin-top: var(--spacing-md);
  font-style: normal;
  font-weight: 700;
  color: var(--color-primary-dark);
}

/* Mobile Responsive */
@media (max-width: 600px) {
  .container {
    padding: 0 var(--spacing-sm);
  }

  .site-header {
    padding: var(--spacing-md) 0;
  }

  section {
    padding: var(--spacing-xl) 0;
  }

  .hero {
    padding: var(--spacing-xl) 0;
  }

  .hero .btn {
    width: 100%;
  }

  .grid {
    grid-template-columns: 1fr;
  }

  .price-card.featured:hover {
    transform: scale(1);
  }

  form {
    padding: 0;
  }
}

/* Desktop Responsive */
@media (min-width: 601px) {
  .hero .container {
    flex-direction: row;
    align-items: center;
    gap: var(--spacing-xl);
  }

  .hero > .container > div:first-child {
    flex: 1;
  }
}

/* Motion Preference */
@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }

  .logo {
    transform: none;
  }

  .logo:hover {
    transform: none;
  }

  .card:hover {
    transform: none;
  }

  .price-card.featured:hover {
    transform: none;
  }

  button:hover,
  .btn:hover {
    transform: none;
  }
}

